use std::{env, error::Error, fs};

use ga_domain::garmin_health::normalize_health_payload;
use serde_json::{Value, json};

#[test]
#[ignore = "requires the synthetic fixture generated by the pinned Python oracle"]
fn matches_pinned_health_normalization() -> Result<(), Box<dyn Error>> {
    let corpus: Vec<(String, String, Value, Value)> =
        serde_json::from_slice(&fs::read(env::var("GA_TEST_GARMIN_HEALTH_CASES")?)?)?;
    for (endpoint, key, payload, expected) in corpus {
        let actual = match normalize_health_payload(&endpoint, &key, &payload) {
            Ok(result) => {
                let samples: Vec<_> = result
                    .samples
                    .into_iter()
                    .map(|sample| {
                        json!([
                            sample.instant.to_string(),
                            sample.metric,
                            sample.unit,
                            sample.value
                        ])
                    })
                    .collect();
                let observations: Vec<_> = result
                    .observations
                    .into_iter()
                    .map(|observation| {
                        json!([
                            observation.metric,
                            observation.unit,
                            observation.value,
                            observation.sequence,
                            observation.observed.map(|value| value.to_string()),
                            observation
                                .interval
                                .map(|(start, end)| [start.to_string(), end.to_string()]),
                        ])
                    })
                    .collect();
                json!({
                    "status": result.status.label(),
                    "fields": result.fields,
                    "samples": samples,
                    "observations": observations,
                    "sleep_interval": result.sleep_interval.map(|(start, end)| [start.to_string(), end.to_string()]),
                })
            }
            Err(_) => json!({"status": "error"}),
        };
        assert!(
            equal(&actual, &expected),
            "{endpoint}: {payload}\nRust: {actual}\nPython: {expected}"
        );
    }
    Ok(())
}

fn equal(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(left), Value::Number(right)) => left.as_f64() == right.as_f64(),
        (Value::Array(left), Value::Array(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right)
                    .all(|(left, right)| equal(left, right))
        }
        (Value::Object(left), Value::Object(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .all(|(key, value)| right.get(key).is_some_and(|other| equal(value, other)))
        }
        _ => left == right,
    }
}
